<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google Ads bağlantısı - AdGuard</title><link rel="stylesheet" href="/assets/app.css"></head>
<body><main class="container"><h1>Google Ads hesapları</h1><p><a href="/dashboard">Kontrol paneli</a></p><?php if(!empty($_SESSION['success'])): ?><p class="success"><?= e($_SESSION['success']) ?></p><?php unset($_SESSION['success']); endif; ?><?php if(!empty($_SESSION['error'])): ?><p class="alert"><?= e($_SESSION['error']) ?></p><?php unset($_SESSION['error']); endif; ?><a class="button" href="/google/connect">Google Ads hesabını bağla</a><table><thead><tr><th>Customer ID</th><th>Durum</th><th>Token bitişi</th><th>İşlem</th></tr></thead><tbody><?php foreach($connections as $connection): ?><tr><td><?= e($connection['customer_id']) ?></td><td><?= e($connection['status']) ?></td><td><?= e($connection['token_expires_at']) ?></td><td><a href="/google/campaigns?id=<?= (int)$connection['id'] ?>">Kampanyaları gör</a> <form method="post" action="/google/disconnect"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$connection['id'] ?>"><button type="submit">Bağlantıyı kaldır</button></form></td></tr><?php endforeach; ?></tbody></table></main></body></html>
